  ],
  "blocking_issues": [],
  "dimensions": [],
  "filters": [
    "product.on_sale = false"
  ],
  "grain": "product（sku）存量快照",
  "limit": 1000,
  "metrics": [
    {
      "caliber": "下架商品数 off_sale_product_cnt：存量计数，COUNT(*) WHERE on_sale = false；按 SKU 计，含 on_sale 为 NULL 的行不计入；与 on_sale_product_cnt 互补但两者相加不等于 product_cnt；time_basis=current，与任何时间区间无关",
      "name": "off_sale_product_cnt"
    }
  ],
  "order_by": [],
  "output_columns": [
    "off_sale_product_cnt"
  ],
  "time_range": {
    "end": null,
    "start": null
  }
}

